"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { z } from "zod/v3";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { ProfileImageUpload } from "@/components/ui/profile-image-upload";
import { UserIcon, MailAtSign01Icon, ArrowRight01Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";

import { useEffect, useState } from "react";

const profileSchema = z.object({
  fullName: z.string().min(2, "Full name must be at least 2 characters."),
  username: z.string().min(3, "Username must be at least 3 characters."),
  avatar: z.string().optional(),
});

type ProfileValues = z.infer<typeof profileSchema>;

interface ProfileStepProps {
  onNext: (data: ProfileValues) => void;
  defaultValues: Partial<ProfileValues>;
}

export const ProfileStep = ({ onNext, defaultValues }: ProfileStepProps) => {
  const [isUsernameDirty, setIsUsernameDirty] = useState(false);

  const form = useForm<ProfileValues>({
    resolver: zodResolver(profileSchema),
    defaultValues: {
      fullName: defaultValues.fullName || "",
      username: defaultValues.username || "",
      avatar: defaultValues.avatar || "",
    },
  });

  const fullName = form.watch("fullName");

  useEffect(() => {
    if (!isUsernameDirty && fullName) {
      const suggestedUsername = fullName
        .toLowerCase()
        .replace(/\s+/g, "")
        .replace(/[^a-z0-9]/g, "");
      form.setValue("username", suggestedUsername, { shouldValidate: true });
    }
  }, [fullName, isUsernameDirty, form]);

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4 rounded-xl border border-border/50 bg-muted/20 p-4">
        <ProfileImageUpload 
           value={form.watch("avatar")} 
           onChange={(url) => form.setValue("avatar", url)} 
        />
        <div className="space-y-0.5">
          <h3 className="text-sm font-semibold tracking-tight">Profile Photo</h3>
          <p className="text-[11px] text-muted-foreground leading-relaxed max-w-[220px]">
             Upload a photo to personalize your workspace. Max 1MB.
          </p>
        </div>
      </div>

      <Form {...form}>
        <form onSubmit={form.handleSubmit(onNext)} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="fullName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Full Name</FormLabel>
                  <FormControl>
                    <div className="relative group">
                       <HugeiconsIcon icon={UserIcon} className="absolute left-2.5 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground transition-colors group-focus-within:text-primary" />
                       <Input className="pl-8 h-8 transition-all" placeholder="John Doe" {...field} />
                    </div>
                  </FormControl>
                  <FormMessage className="text-[10px]" />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="username"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Username</FormLabel>
                  <FormControl>
                    <div className="relative group">
                       <HugeiconsIcon icon={MailAtSign01Icon} className="absolute left-2.5 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground transition-colors group-focus-within:text-primary" />
                       <Input 
                          className="pl-8 h-8 transition-all" 
                          placeholder="johndoe" 
                          {...field} 
                          onChange={(e) => {
                            field.onChange(e);
                            setIsUsernameDirty(true);
                          }}
                       />
                    </div>
                  </FormControl>
                  <FormMessage className="text-[10px]" />
                </FormItem>
              )}
            />
          </div>

          <p className="text-[11px] text-muted-foreground/70 italic px-1">
             Your unique handle on the platform.
          </p>

          <Button type="submit" className="w-full mt-4" size="lg">
             Continue
             <HugeiconsIcon icon={ArrowRight01Icon} className="ml-2" size={18} />
          </Button>
        </form>
      </Form>
    </div>
  );
};
